  h=new H();h.start();h.f.pos=new PestTargets.Point(0,75,-96);h.positions.observe(1,1,new PlayerPositionReceipts.Position(0,75,-96),true,S);h.task.tick(S);attackAt=0;for(int i=2;i<12&&h.f.attacks==0;i++){h.task.tick(i*S);attackAt=i*S;}h.f.changed=true;h.task.tick(attackAt+5*S);check(h.task.state()==GreenhouseTask.State.TIMED_OUT&&h.f.attacks==1&&h.f.stops==1,"no server harvest proof: no retries/fake success/old-tool restoration");
